/* S1-06 — WF5 : présenter l'échec capturé par l'Error Trigger.
   Entrée : le payload n8n d'erreur (execution.*, workflow.*), injecté par n8n.
   Sortie : { workflow, message } — sans réseau ici (JsTaskRunner, AGENTS.md §10).
   Garde : champs manquants ⇒ fallback explicite, jamais un plantage de WF5 lui-même. */
const j = $input.first().json || {};
const execution = (j && j.execution) || {};
const erreur = (execution && execution.error) || null;
const wf = (j && j.workflow) || {};
const brut = erreur && typeof erreur.message === 'string' && erreur.message.trim() !== ''
  ? erreur.message
  : (erreur && typeof erreur.stack === 'string' ? erreur.stack : null);
const nomWorkflow = typeof wf.name === 'string' && wf.name.trim() !== '' ? wf.name : 'workflow inconnu (WF5)';
const message = [
  'echec workflow n8n',
  '« ' + nomWorkflow + ' »',
  execution.id != null ? 'exécution ' + execution.id : null,
  typeof execution.lastNodeExecuted === 'string' && execution.lastNodeExecuted.trim() !== '' ? 'dernier nœud : ' + execution.lastNodeExecuted : null,
  brut ? String(brut).slice(0, 400) : null,
].filter(Boolean).join(' — ');
const ALIAS_RUNS = { 'WF1 - Collecte': 'wf1-collecte' };
/* le champ runs.workflow est la clé du contrat (constante posée par WF1, « wf1-collecte »),
   PAS le nom n8n — d'où la correspondance : nom n8n exact, ou nom de copie de test
   « Nom (suffixe) » via le préfixe connu (preuve par copies jetables S1-06). */
const aliasRuns = Object.keys(ALIAS_RUNS).find((k) => nomWorkflow === k || nomWorkflow.startsWith(k + ' ('));
const workflowRuns = aliasRuns !== undefined ? ALIAS_RUNS[aliasRuns] : nomWorkflow;
return [{ json: { workflow: workflowRuns, workflow_n8n: nomWorkflow, message } }];

/* S1-06 — WF5 : y a-t-il une ligne `runs` encore `running` du même workflow à clore ?
   - Oui (l'échec est survenu APRÈS ouverture de la ligne) → mode 'update' : on clôt la plus
     récente (started_at décroissant). Conforme à la règle « une ligne runs par exécution ».
   - Non (l'échec est survenu avant toute ouverture, ou la lecture a elle-même échoué —
     l'item d'erreur ne porte pas d'`id`) → mode 'create' : la ligne d'erreur est à créer.
   Aucun réseau ici (JsTaskRunner, AGENTS.md §10). */
const base = $('Présentation de l\'échec (S1-06)').first().json;
const enRunning = $input.all()
  .filter((it) => it.json && typeof it.json.id === 'string' && it.json.status === 'running')
  .sort((a, b) => String(b.json.started_at || '').localeCompare(String(a.json.started_at || '')));
if (enRunning.length === 0) {
  return [{ json: { ...base, mode: 'create' } }];
}
return [{ json: { ...base, mode: 'update', run_id: enRunning[0].json.id } }];
